import pandas as pd
import re

def parse_notes(notes_str):
    items = None
    adj_pct = 0.0
    fee = 0.0
    waive = False

    if pd.isna(notes_str):
        return items, adj_pct, fee, waive

    parts = str(notes_str).split(';')
    for part in parts:
        part = part.strip()
        if not part:
            continue
        if '=' in part:
            key, val = part.split('=', 1)
            key = key.strip().lower()
            val = val.strip()
            if key == 'items':
                try:
                    items = int(val)
                except ValueError:
                    pass
            elif key == 'adj':
                try:
                    if val.endswith('%'):
                        adj_pct = float(val[:-1]) / 100.0
                    else:
                        adj_pct = float(val) / 100.0
                except ValueError:
                    pass
            elif key == 'fee':
                try:
                    fee = float(val)
                except ValueError:
                    pass
            elif key == 'waive':
                waive = (val.lower() == 'true')

    return items, adj_pct, fee, waive

df = pd.read_csv('/app/dataset/data.csv')
for idx, row in df.dropna(subset=['notes']).head(15).iterrows():
    print('Notes:', repr(row['notes']))
    print('Parsed:', parse_notes(row['notes']))
"
